<script setup>
import {ref} from 'vue';import {loadConsumerRequests,updateConsumerRequest} from '../services/consumerManagement';
const rows=ref([]),busy=ref(false),error=ref(''),opened=ref(false),cursor=ref(null),more=ref(false);
async function load(reset=true){if(busy.value)return;busy.value=true;error.value='';try{const page=await loadConsumerRequests(reset?null:cursor.value);rows.value=reset?page.rows:[...rows.value,...page.rows];cursor.value=page.cursor;more.value=page.hasMore;opened.value=true;}catch{error.value='No pudimos consultar las solicitudes.';}finally{busy.value=false;}}
async function update(row,status){if(busy.value)return;busy.value=true;error.value='';try{await updateConsumerRequest(row.id,status);row.status=status;}catch{error.value='No pudimos actualizar la gestión.';}finally{busy.value=false;}}
</script><template><section class="consumer-admin"><h2>Solicitudes de baja y arrepentimiento</h2><p>Revisá la identidad por el correo de la cuenta antes de cancelar o devolver. Cambiar el estado aquí no ejecuta cobros, bajas ni devoluciones en Mercado Pago.</p><button :disabled="busy" @click="load()">Consultar solicitudes</button><p v-if="error" role="alert">{{error}}</p><div v-if="opened" class="catalog-scroll"><table class="catalog-table"><thead><tr><th>Comprobante</th><th>Recibida</th><th>Solicitud</th><th>Correo y referencia</th><th>Estado</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.receipt}}</td><td>{{r.createdAt?new Date(r.createdAt).toLocaleString('es-AR',{timeZone:'America/Argentina/Buenos_Aires'}):'—'}}</td><td>{{r.kind}}<p>{{r.message}}</p></td><td>{{r.email}}<p>{{r.reference}}</p></td><td><select :disabled="busy" :value="r.status" @change="update(r,$event.target.value)"><option value="received">Recibida</option><option value="in_progress">En gestión</option><option value="resolved">Resuelta</option></select></td></tr><tr v-if="!rows.length"><td colspan="5">No hay solicitudes registradas.</td></tr></tbody></table><button v-if="more" :disabled="busy" @click="load(false)">Cargar 20 anteriores</button></div></section></template>
<style scoped>.consumer-admin{margin:24px 0;padding:24px;border:1px solid #536779;border-radius:12px}.consumer-admin .catalog-scroll{overflow:auto}.consumer-admin td{max-width:250px;overflow-wrap:anywhere}</style>
